INSERT INTO articles (slug,title,teaser,body,category,topic,region,kind,author,image,source_name,source_url,status,published_at,updated_at,meta_title,meta_description,focus_keyword,keywords,image_alt,image_prompt,faq,service) VALUES ('rsv-impfung-oesterreich-2026-ab-60-unterschaetzt-oevih','RSV-Impfung in Österreich: Experten warnen vor unterschätzter Welle','Das RS-Virus führt bei Älteren ähnlich oft ins Spital wie die Grippe, doch viele Fälle werden nicht erfasst. Wem die RSV-Impfung empfohlen wird und was sie kostet.','Die **RSV-Impfung** rückt vor Beginn der Wintersaison in den Fokus: Laut einer Aussendung des Österreichischen Verbands der Impfstoffhersteller (ÖVIH) vom 28. Oktober wird das Respiratorische Synzytial-Virus in Österreich nach wie vor deutlich unterschätzt. Internationale Studien zeigen demnach, dass RSV bei Erwachsenen ähnlich häufig zu schweren Verläufen und Spitalsaufenthalten führt wie die Influenza.

## Warum RSV-Fälle oft nicht erfasst werden

Dass die heimischen Zahlen das tatsächliche Ausmaß nicht abbilden, hat laut der Aussendung mehrere Gründe. Häufig wird kein PCR-Test gemacht, Meldungen an das SARI-Dashboard sind unvollständig, und auch die Codierung der Diagnosen in den Spitälern erfolgt nicht immer korrekt.

Im niedergelassenen Bereich ist das Virus zudem schwerer zu erkennen als die Grippe. Typische Influenza-Anzeichen wie Fieber, Muskelschmerzen oder starke Erschöpfung treten bei RSV seltener auf. Die Belastung durch Arztbesuche, Medikamente und Krankenstände sei dennoch vergleichbar, die Dunkelziffer wird als hoch eingeschätzt.

Der Infektiologe Robert Krause von der MedUni Graz verweist darauf, dass die Zahl der stationär behandelten RSV-Fälle in Österreich jene der COVID-19-Fälle bereits erreicht habe. Die Betroffenen im Spital sind im Schnitt rund 67 Jahre alt. Krause vermutet, dass sich viele Großeltern bei ihren Enkelkindern anstecken.

## Wann die RSV-Saison beginnt

In Europa startet die RSV-Saison üblicherweise im November oder Dezember. Der Höhepunkt wird meist im Jänner und Februar erreicht, abklingen dürfte die Welle im März oder April. Für einen Schutz in der kommenden Saison ist der Zeitraum vor Saisonbeginn daher entscheidend.

Besonders gefährdet sind neben älteren Menschen auch Säuglinge. US-Daten zufolge gehen im Winter bis zu ein Viertel der Spitalsaufnahmen von Babys unter einem Jahr auf RSV zurück.

## Wem der Impfplan die RSV-Impfung empfiehlt

Der Impfplan Österreich 2026/2027 sieht folgende Empfehlungen vor:

- alle Personen ab 60 Jahren, mit besonderem Nachdruck ab 75 Jahren sowie für Bewohnerinnen und Bewohner von Alten- und Pflegeheimen
- Erwachsene ab 18 Jahren unabhängig vom Alter, wenn schwere Grunderkrankungen vorliegen, etwa chronische Lungenleiden wie COPD, Herzerkrankungen oder Immundefekte
- Schwangere, deren Geburtstermin zwischen Oktober und März liegt, um das Neugeborene zu schützen

Für Säuglinge und Kleinkinder gibt es als Alternative eine kostenfreie passive Immunisierung, die vor oder während der Saison verabreicht wird.

Studien zeigen laut ÖVIH, dass die RSV-Krankenhausaufnahmen in der ersten Saison nach der Impfung um mehr als 90 Prozent zurückgehen. Krause geht allerdings davon aus, dass sich bisher nur wenige Impfberechtigte von sich aus impfen lassen, weil die Impfung noch relativ neu und wenig bekannt sei.

## RSV-Impfung: Kosten und Forderungen

Für Erwachsene und Schwangere ist die RSV-Impfung derzeit selbst zu bezahlen. Die Fachleute in der Aussendung fordern daher einen kostenlosen und niederschwelligen Zugang für Risikogruppen sowie die rasche Aufnahme in das öffentliche Impfprogramm für Erwachsene. Hausärztinnen und Hausärzte sollten Patientinnen und Patienten über 60 sowie Risikopersonen gezielt informieren. Betriebsimpfungen könnten zudem chronisch Kranke im Erwerbsalter erreichen.

Zu berücksichtigen ist, dass der ÖVIH die Interessen der Impfstoffhersteller vertritt. Die Empfehlungen selbst stammen aus dem offiziellen Impfplan. Wer zu einer der genannten Gruppen gehört, sollte die Impfung am besten mit der Hausärztin oder dem Hausarzt besprechen, idealerweise noch vor Beginn der Saison im November.','gesundheit','Medizin',NULL,'news','Presseinfo Redaktion','/assets/img/artikel/rsv-impfung-oesterreich-2026-ab-60-unterschaetzt-oevih.webp','APA-OTS / Österreichischer Verband der Impfstoffhersteller (ÖVIH)','https://www.ots.at/presseaussendung/OTS_20261028_OTS0003/rsv-infektionen-in-oesterreich-immer-noch-unterschaetzt','published','2026-10-28T17:50:00.000Z','2026-10-28T17:43:53.182Z','RSV-Impfung Österreich: Wer sich jetzt schützen sollte','RSV-Impfung in Österreich: Fachleute halten das RS-Virus für unterschätzt. Wem der Impfplan sie empfiehlt, was sie kostet und wann die Saison beginnt.','RSV-Impfung','["RSV-Impfung","RSV Österreich","RS-Virus","RSV-Saison 2026","RSV-Impfung ab 60","RSV-Impfung Kosten","RSV Impfplan Österreich 2026/2027","RSV Schwangerschaft Impfung","Atemwegsinfekt Winter"]','RSV-Impfung in einer Arztpraxis in Österreich vor Beginn der Wintersaison','Austrian general practitioner''s consultation room in autumn, a vaccine vial and a prepared syringe on a white tray next to a patient''s sleeve rolled up, older adult seen from behind and only partially, warm window light, rainy Vienna street visible blurred through the window, no text, no logos, no readable signs','[{"q":"Wer sollte sich laut Impfplan gegen RSV impfen lassen?","a":"Alle ab 60 Jahren, besonders ab 75 und in Pflegeheimen, Erwachsene ab 18 mit schweren Grunderkrankungen sowie Schwangere mit Geburtstermin zwischen Oktober und März."},{"q":"Was kostet die RSV-Impfung in Österreich?","a":"Für Erwachsene und Schwangere ist die Impfung derzeit selbst zu bezahlen. Für Säuglinge und Kleinkinder gibt es eine kostenfreie passive Immunisierung."},{"q":"Wann beginnt die RSV-Saison?","a":"Meist im November oder Dezember, mit Höhepunkt im Jänner und Februar. Sie endet in der Regel im März oder April."}]',0) ON CONFLICT(slug) DO UPDATE SET title=excluded.title, teaser=excluded.teaser, body=excluded.body, category=excluded.category, topic=excluded.topic, region=excluded.region, kind=excluded.kind, author=excluded.author, source_name=excluded.source_name, source_url=excluded.source_url, status=excluded.status, published_at=excluded.published_at, updated_at=excluded.updated_at, meta_title=excluded.meta_title, meta_description=excluded.meta_description, focus_keyword=excluded.focus_keyword, keywords=excluded.keywords, image_alt=excluded.image_alt, image_prompt=excluded.image_prompt, faq=excluded.faq, service=excluded.service, image=COALESCE(excluded.image, articles.image);
